steps.script:
for b in tree.current_scene.find_children("*", "Button", true, false):
	if str(b.name) == "SettingsButton":
		b.pressed.emit()
		return "clicked"
return "not found"

var m = tree.root.find_children("SettingsMenu", "", true, false)
if m.is_empty():
	return "missing"
m[0]._on_tab_pressed(4)
return "ok"
